const $=s=>document.querySelector(s);
const studies=[{title:'Anatomia de uma mariposa',category:'Animais',image:'assets/moth.svg',caption:'Ilustração digital de demonstração',body:'Composição vetorial criada para demonstrar a organização do portfólio. Não é desenho, tatuagem ou estudo realizado por Paulo.'},{title:'O peso da luz',category:'Estátuas',image:'assets/marble.jpg',caption:'Referência fotográfica · The Met',body:'Marble statue of a member of the imperial family. Escultura romana, 27 a.C.–68 d.C. The Metropolitan Museum of Art. Imagem de domínio público. Não é obra de Paulo. Fonte: https://www.metmuseum.org/art/collection/search/257640'},{title:'Forma antes do detalhe',category:'Simbólico',image:'assets/volume.svg',caption:'Exemplo digital · volume e espaço',body:'Esfera digital ilustrativa para testar a apresentação de composições. Não representa estudo autoral de Paulo. Substitua este exemplo quando houver material real.'}];
function el(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e;}
function show(title,body,image){const box=$('#detail-content');box.replaceChildren();if(image){const img=el('img');img.src=image;img.alt=title;box.append(img);}const h=el('h2',title);h.id='detail-title';box.append(h,el('p',body));$('#detail').showModal();}
$('.close').onclick=()=>$('#detail').close();
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function gallery(filter='Todos'){const items=studies.filter(s=>filter==='Todos'||s.category===filter);$('#gallery').replaceChildren();items.forEach(s=>{const button=el('button',null,'study');const wrap=el('div',null,'study-image');const img=el('img');img.src=s.image;img.alt=s.title+' — '+s.caption;img.loading='lazy';wrap.append(img,el('span','DEMONSTRAÇÃO / '+s.category.toUpperCase()));button.append(wrap,el('h3',s.title+' ↗'),el('small',s.caption));button.onclick=()=>show(s.title,s.body,s.image);$('#gallery').append(button);});$('#count').textContent=items.length+' exemplos · 0 obras autorais';}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));gallery(b.dataset.filter);});gallery();
$('#compare').oninput=e=>{const v=Number(e.target.value);$('#before').style.clipPath=`inset(0 ${100-v}% 0 0)`;$('#compare-line').style.left=v+'%';$('#position').value=v+'%';};
fetch('content.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{data.articles.forEach(a=>{const button=el('button',null,'article');button.append(el('small',a.category.toUpperCase()+(a.demo?' / TEXTO DEMO':'')),el('h3',a.title),el('p',(a.body.split('\n\n')[1]||a.body).slice(0,110)+'…'),el('span','Ler anotação ↗'));button.onclick=()=>show(a.title,a.body);$('#articles').append(button);});}).catch(()=>{$('#articles').textContent='As anotações não carregaram. Atualize a página ou abra o projeto pelo servidor local indicado no README.';});
